#!/usr/bin/env python3
"""Reproduce pinned public guidance/technical-documentation snapshots. No LLM calls.
Uses the configured gh CLI; never executes downloaded repository code.
"""
import base64,datetime,hashlib,json,pathlib,subprocess
ROOT=pathlib.Path(__file__).resolve().parents[1];REPO='usds/playbook';REV='f5d71f1939efe87db9f0be414bcfa7c489e01c19'
def api(path):return json.loads(subprocess.check_output(['gh','api',path],text=True))
def content(path,repo=REPO,revision=REV):
 data=api('repos/'+repo+'/contents/'+path+'?ref='+revision)
 if data.get('encoding')!='base64' or data.get('size',0)>200000:raise ValueError('Unexpected or oversized source')
 raw=base64.b64decode(data['content']);assert len(raw)==data['size'];assert hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==data['sha'];raw.decode('utf-8',errors='strict');return raw

def main():
 assert api('repos/'+REPO)['private'] is False,'Only public reference repositories are permitted'
 notice=content('README.md');assert b'public domain within the United States' in notice and b'CC0 1.0 Universal' in notice
 folder=ROOT/'reference-library';(folder/'sources').mkdir(exist_ok=True);(folder/'notices').mkdir(exist_ok=True)
 notice_path='notices/usds-playbook-README.md';(folder/notice_path).write_bytes(notice)
 plans=[('01','Understand what people need','User needs and evidence plan',['users','user','research','usability','design','accessibility'], 'Outline user groups, research methods, documented findings and validation activities. Populate findings only from supplied bidder evidence; otherwise mark them as needing input. Do not claim research has occurred without evidence.'),('04','Build the service using agile and iterative practices','Delivery approach and feedback loop',['agile','iterative','delivery','sprints','backlog','testing','acceptance'],'Outline prioritised work packages, feedback checkpoints, quality practices and acceptance activities. Use current buyer instructions and evidenced delivery capacity. Do not import the reference\'s example durations, release frequency or technology choices as buyer requirements.'),('12','Use data to drive decisions','Measurement and operational review',['metrics','monitoring','performance','latency','measurement','operations','outcomes'],'Outline service measures, how they would be collected, reporting ownership and a review loop. Obtain proposed targets and tool capabilities from current buyer instructions and bidder evidence; do not invent an uptime promise or claim monitoring is already deployed.')]
 manifest=json.loads((folder/'catalogue.json').read_text());new=[]
 for number,title,pattern_title,tags,guidance in plans:
  raw=content('_plays/'+number+'.md');assert ('title: '+title).encode() in raw
  sid='usds-playbook-'+number;source_path='sources/'+sid+'.md';(folder/source_path).write_bytes(raw)
  new.append({'id':sid,'title':title,'sourceUrl':f'https://github.com/{REPO}/blob/{REV}/_plays/{number}.md','supportingUrls':[],'publisher':'United States Digital Service','jurisdiction':'US federal','sector':'IT','documentType':'government_guidance','sourceRevision':REV,'reviewStatus':'approved','approvalScope':'offline_pilot','reuseStatus':'permitted','licenceEvidenceUrl':f'https://github.com/{REPO}/blob/{REV}/README.md','reuseBasis':'The pinned repository README explicitly states United States Government public-domain status and worldwide CC0 dedication. Preserve the notice. Offline structure guidance only; no endorsement or full winning-response claim.','reviewedBy':'Codex source/notice review; offline pilot only, not production approval','reviewedAt':datetime.datetime.now(datetime.timezone.utc).date().isoformat(),'sha256':hashlib.sha256(raw).hexdigest(),'sourcePath':source_path,'licencePath':notice_path,'licenceSha256':hashlib.sha256(notice).hexdigest(),'awardStatus':'not_applicable','patterns':[{'id':'structure-'+number,'title':pattern_title,'guidance':guidance,'locator':f'Play {int(number)}; Checklist and Key Questions','tags':tags}],'limitations':'Government delivery guidance, not a proposal response, award evidence, current procurement law or proof of bidder capabilities. Historical guidance must not override the current solicitation.'})
 repo='buchanan-edwards/gsa-18f-2015-07';revision='dddd3fe4a597f56d778b7d711c234e5af146c8e3'
 assert api('repos/'+repo)['private'] is False
 raw=content('gsa-18f-acumen/README.md',repo,revision);licence=content('gsa-18f-acumen/LICENSE.txt',repo,revision)
 assert b'Acumen GSA Agile Prototype' in raw and b'associated documentation files' in licence and b'The MIT License' in licence
 source_path='sources/acumen-agile-prototype.md';notice_path='notices/acumen-MIT.txt';(folder/source_path).write_bytes(raw);(folder/notice_path).write_bytes(licence)
 new.append({'id':'acumen-agile-prototype','title':'Acumen GSA Agile Prototype response documentation','sourceUrl':f'https://github.com/{repo}/blob/{revision}/gsa-18f-acumen/README.md','supportingUrls':['https://github.com/18F/ads-bpa/blob/e92fd50019b83d65396cf347c48e5fd9a7fcb81c/data/vendors.yml'],'publisher':'Acumen Solutions response documentation, hosted in Buchanan & Edwards repository','jurisdiction':'US federal','sector':'IT','documentType':'technical_submission_documentation','sourceRevision':revision,'reviewStatus':'approved','approvalScope':'offline_pilot','reuseStatus':'permitted','licenceEvidenceUrl':f'https://github.com/{repo}/blob/{revision}/gsa-18f-acumen/LICENSE.txt','reuseBasis':'Adjacent project MIT licence expressly includes associated documentation files; retain its copyright and permission notice. No linked assets fetched, no endorsement, and no vendor facts transferred into guidance. Offline structural analysis only.','reviewedBy':'Codex source/notice review; offline pilot only, not production approval','reviewedAt':datetime.datetime.now(datetime.timezone.utc).date().isoformat(),'sha256':hashlib.sha256(raw).hexdigest(),'sourcePath':source_path,'licencePath':notice_path,'licenceSha256':hashlib.sha256(licence).hexdigest(),'awardStatus':'unverified','awardAssociation':'Official 18F pool-three list names Acumen Solutions Inc. This establishes a vendor lead, not that this exact document/revision was the evaluated winning submission.','patterns':[{'id':'role-coverage','title':'Role, capacity and responsibility structure','guidance':'Provide a role-and-responsibility table keyed to the buyer evaluation needs. State resource assumptions and source-backed qualifications. Do not import names, staffing counts, certifications or technologies from the reference.','locator':'Project Team; Labor Category','tags':['team','capacity','staffing','roles','resources','responsibilities']},{'id':'approach-rationale','title':'Explain the technical approach and trade-offs','guidance':'Organise the approach around the current buyer objectives, options considered, rationale and evidence. Do not adopt this historical prototype technology stack or its claims as your own.','locator':'Approach','tags':['technical','architecture','approach','tradeoffs']}],'limitations':'Historical prototype/response documentation, not a verified full winning proposal. Reuse is limited to source-attributed structure guidance in the offline pilot. Third-party links/assets, names, claims and technology recommendations are not imported into bidder evidence.'})
 ids={r['id'] for r in new};manifest['records']=[r for r in manifest['records'] if r['id'] not in ids]+new;(folder/'catalogue.json').write_text(json.dumps(manifest,indent=2)+'\n')
 print('Collected 3 government-guidance snapshots and 1 technical-documentation snapshot with notices; offline only, no full winning-proposal or production approval claim.')
if __name__=='__main__':main()
